list.query:
from(bucket: "twin") |> range(start: v.timeRangeStart, stop: v.timeRangeStop)
  |> filter(fn: (r) => r._measurement == "deviation" and r.case == "${case}" and r._field == "flagged" and r._value == true)
  |> map(fn: (r) => ({_time: r._time, _value: "deviation: " + r.signal}))

from(bucket: "twin") |> range(start: v.timeRangeStart, stop: v.timeRangeStop)
  |> filter(fn: (r) => r._measurement == "warning" and r.case == "${case}" and r._field == "alert" and r._value == true)
  |> map(fn: (r) => ({_time: r._time, _value: "hypotension alert"}))
